if($argv.Count -ne 17 -or $argv[0] -ne '-S' -or $argv[2] -ne '-B' -or $argv[4] -ne '-G' -or $argv[6] -ne '-A' -or $argv[8] -ne '-DLY_PACKAGE_SERVER_URLS:STRING=' -or $argv[14] -notlike '-DJE_PYTHON_ROOT:PATH=*' -or $argv[15] -ne "-DJE_PYTHON_WHEELHOUSE:PATH=$wheel" -or $argv[16] -ne '-DCMAKE_MESSAGE_LOG_LEVEL:STRING=VERBOSE'){throw 'root positive configure argv validation failed'};foreach($element in $argv){if($element -match '\s-D(?:LY_|JE_|CMAKE_)'){throw 'argv element contains a second option'}}
